import{z as l,x as s,o as B,c as p,q as n,j as A,D as e,d as a,s as o,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"时序交叉验证的深化","description":"","frontmatter":{"title":"时序交叉验证的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-tscv-deep.md","filePath":"quant/fml-tscv-deep.md","lastUpdated":1791063341000}'),d={name:"quant/fml-tscv-deep.md"};function m(c,E,u,C,D,f){const t=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=n('<h1 id="时序交叉验证的深化" tabindex="-1">时序交叉验证的深化 <a class="header-anchor" href="#时序交叉验证的深化" aria-label="Permalink to &quot;时序交叉验证的深化&quot;">​</a></h1><div class="epigraph"><p>折怎么切，决定折外分数配不配当裁判；对相依数据，随机打乱不是切分，是重写了数据的生成过程。</p><footer>—— 据 Racine, Journal of Econometrics, 2000；López de Prado, Advances in Financial Machine Learning, 2018 整理</footer></div><p><a href="/quant/fml-model-selection-protocol">上一课</a>把「挑谁」写成协议，协议的裁判是折外分数；缺口是裁判自身的资格——折怎么切，决定折外还算不算折外。<a href="/quant/cv-leakage-finance">交叉验证在金融中的泄漏</a>立了泄漏路径，<a href="/quant/purge-embargo">Purge 与 Embargo</a>给了清洗机制，<a href="/quant/cpcv-lopez">Combinatorial Purged CV</a>给了路径视角。本课深化切分工程：四个参数怎么标定、截面与时序怎么组合、路径怎么聚合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>切分是四参数决策：块结构、清洗规则、路径数、聚合口径；实践里它们常被默认值顶替——五折随机、固定 \\(h\\) 的 purge、单条滚动路径。三个具体的坑。Embargo 长度拍脑袋：与特征最长滞后无关的 \\(E\\)，小了不够（测试块后的训练点仍携带同一冲击），大了白白扔掉稀缺样本。截面策略用单资产时序折：截面信号按日期分组切分才成立，否则同一共因子日横跨训练与测试两侧。单路径幻觉：一条滚动路径只是路径分布的一个实现，拿一个样本做推断，冠军的选择判据本身就是噪声。</p><p><span class="marginnote">Embargo 可以类比考试隔离：考完的班级（测试块）与还没考的班级（训练侧）之间隔一段走廊时间，防止答案——同一次冲击的信息——通过相邻座位传出去。走廊多长，取决于回声在数据里传多远。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>切分按四步落参数。块结构：时间块宽度不小于标签视野加特征最长滞后；截面信号按日期分组切分，块内保持完整交易日。清洗：purge 按每条样本的真实标签结束时间 \\(t_{i,1}\\)（<a href="/quant/triple-barrier">Triple Barrier</a> 的首达时间）删除，不用固定 \\(h\\) 的保守上界；embargo \\(E\\) 由特征与残差的滞后结构标定——看自相关截尾的位置加缓冲，不看习惯。路径：评估用 <a href="/quant/cpcv">CPCV</a> 生成多条 purged 路径看分布，部署演练用遵守时间顺序的单条<a href="/quant/walk-forward">滚动</a>；前者评选择过程，后者排练执行，两者不互相替代。聚合：报告路径分布的中位数、分位与低于中位的频率，不只报均值；所有预处理的 <code>fit</code> 停在各折训练段内。</p><p><span class="marginnote">块宽的数字实例：标签视野 5 天，特征含最长 22 天滞后的月频宏数据，块宽就得不小于 \\(5+22=27\\) 个交易日。用「五折随机」的默认值，等于让 22 天的回声留在训练与测试两侧互相偷听。</span></p><p><span class="marginnote">CPCV 翻译成大白话：把时间轴切成若干块，每次抽 2 块当测试、其余当训练，穷举各种组合——同一段行情会在不同组合里轮换「考题」与「复习材料」的角色，最后得到冠军成绩的一个分布，而不是一次运气的抽样。</span></p>',10)),(B(),A(i,null,{default:e(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAB%5B%22%E6%A0%87%E7%AD%BE%E7%BB%93%E6%9D%9F%E6%97%B6%E9%97%B4%20t_i1%20%E4%B8%8E%E7%89%B9%E5%BE%81%E6%9C%80%E9%95%BF%E6%BB%9E%E5%90%8E%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%E5%AE%BD%EF%BC%9A%E8%A7%86%E9%87%8E%E5%8A%A0%E6%BB%9E%E5%90%8E%EF%BC%8C%E6%8C%89%E6%97%A5%E6%9C%9F%E5%88%86%E7%BB%84%22%5D%0A%20%20BLK%20--%3E%20PG%5B%22Purge%EF%BC%9A%E5%88%A0%E9%99%A4%E6%A0%87%E7%AD%BE%E9%87%8D%E5%8F%A0%22%5D%0A%20%20PG%20--%3E%20EM%5B%22Embargo%EF%BC%9AE%20%E5%8F%96%E8%87%AA%E7%9B%B8%E5%85%B3%E6%88%AA%E5%B0%BE%E5%8A%A0%E7%BC%93%E5%86%B2%22%5D%0A%20%20EM%20--%3E%20PATH%5B%22%E8%B7%AF%E5%BE%84%EF%BC%9ACPCV%20%E8%AF%84%E8%BF%87%E7%A8%8B%EF%BC%8C%E6%BB%9A%E5%8A%A8%E7%BB%83%E6%89%A7%E8%A1%8C%22%5D%0A%20%20PATH%20--%3E%20AGG%5B%22%E8%81%9A%E5%90%88%EF%BC%9A%E8%B7%AF%E5%BE%84%E5%88%86%E5%B8%83%EF%BC%8C%E9%9D%9E%E5%8D%95%E7%82%B9%E5%9D%87%E5%80%BC%22%5D%0A%20%20AGG%20--%3E%20JUDGE%5B%22%E4%BA%A4%E4%BB%98%E5%8D%8F%E8%AE%AE%EF%BC%9A%E9%85%8D%E5%BE%97%E5%BD%93%E8%A3%81%E5%88%A4%E7%9A%84%E6%8A%98%E5%A4%96%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[a("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,[a("随机折为什么失效：泄漏的三条通道——重叠标签、全样本统计、共同因子日——共享一个根源，训练看到了测试的时间邻居；相依数据的泛化误差要可估，训练与测试的条件分布必须可分，随机折让二者几乎重合，折外分数向样本内收敛。Embargo 为什么有长度：短程自相关让相邻点共享同一冲击，\\(E\\) 的功能是让测试块信息在训练侧衰减到可忽略；自相关在滞后三处截尾，\\(E\\) 就取三加缓冲，与「习惯上隔一天」无关。多路径为什么必要：单路径上的冠军排名是路径噪声的函数；多路径回答的是「冠军是否稳定地好」，其分布直接接上一课 "),r("a",{href:"/quant/pbo"},"PBO"),a(" 的输入——过程质量与候选质量在同一个坐标系里读。")],-1)),(B(),A(i,null,{default:e(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E6%97%A5%E9%A2%91%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20R%5B%22%E9%9A%8F%E6%9C%BA%E6%8A%98%EF%BC%9A%E6%8C%89%E6%A0%B7%E6%9C%AC%E6%89%93%E6%95%A3%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E5%90%8C%E4%B8%80%E5%85%B1%E5%9B%A0%E5%AD%90%E6%97%A5%E6%A8%AA%E8%B7%A8%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E6%8A%98%E5%A4%96%E5%88%86%E6%95%B0%E5%90%91%E6%A0%B7%E6%9C%AC%E5%86%85%E6%94%B6%E6%95%9B%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%88%86%E7%BB%84%E5%88%87%E5%88%86%EF%BC%9A%E6%95%B4%E5%9D%97%E6%97%A5%E6%9C%9F%E5%BD%92%E5%B1%9E%E4%B8%80%E4%BE%A7%22%5D%0A%20%20G%20--%3E%20G1%5B%22%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%B5%8B%E8%AF%95%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%88%86%E5%B8%83%E5%8F%AF%E5%88%86%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E6%8A%98%E5%A4%96%E5%88%86%E6%95%B0%E9%85%8D%E5%BD%93%E8%A3%81%E5%88%A4%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：多路径只报平均分。两条路径一优一劣、均值尚可，与两条都平庸，是完全不同的结论；分布的中位数与「低于中位的频率」才回答上一课的问题——冠军是稳定地好，还是碰巧这次好。</span></p><p><span class="marginnote">\\(E\\) 的单位是样本不是天：若特征含月频宏数据，可得滞后约三周，用「隔一天」定的 embargo 在这类特征面前形同虚设；标定 \\(E\\) 先列特征清单里最慢的可用滞后。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>滚动检验的协议细节与 CPCV 的组合机制已有专课，本课只定参数。切分不修复前视、成本与生存偏差——这些错误会被忠实复制进每一条路径，路径越多样，错误的置信度反而越高。切分也假定<a href="/quant/fml-feature-store-deep">特征存储</a>的点时契约成立：可得时间错位的列会让最严格的清洗也拦不住泄漏。块宽、\\(E\\)、路径数本身是超参数，标定它们的尝试计入 \\(N\\) 台账；在切分方案上挑最好看的那个，是第二层选择，仍归上一课的协议管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切分四参数：块结构、清洗规则、路径数、聚合口径；默认值顶替它们是折外失效的主因。</li><li>Purge 用每条样本的真实 \\(t_{i,1}\\)，embargo 由滞后结构标定，不用习惯值。</li><li>截面信号按日期分组切分；块宽不小于标签视野加特征最长滞后。</li><li>CPCV 多路径评选择过程，单条滚动演练执行；报告分布而非均值。</li><li>出处：Racine, <em>Journal of Econometrics</em>, 2000；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018，第 7 章；Bergmeier and Benítez, <em>Pattern Recognition</em>, 2012。</li></ul>',6))])}const F=l(d,[["render",m]]);export{g as __pageData,F as default};
